'use strict';
// 디자인 검토 전용: 네트워크, 인증, 쿠키, 로컬 저장소를 사용하지 않습니다.
const $ = s => document.querySelector(s);
const $$ = s => [...document.querySelectorAll(s)];
const esc = x => String(x ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons = {grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.9 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',check:'M9 11l3 3L22 4 M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11',book:'M4 3h6a3 3 0 0 1 3 3v15a4 4 0 0 0-4-2H3V3z M13 6a3 3 0 0 1 3-3h5v16h-4a4 4 0 0 0-4 2',chat:'M21 11.5a8.4 8.4 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.4 8.4 0 0 1-3.8-.9L3 21l1.9-5.7A8.4 8.4 0 0 1 4 11.5a8.5 8.5 0 0 1 4.7-7.6 8.4 8.4 0 0 1 3.8-.9h.5a8.5 8.5 0 0 1 8 8v.5',chart:'M3 3v18h18 M7 14l4-4 4 2 6-7',edit:'M12 20h9 M16.5 3.5a2.1 2.1 0 0 1 3 3L9 17l-4 1 1-4z',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M19 5l-2 2 M7 17l-2 2',search:'M21 21l-5-5 M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',chevron:'M9 5l7 7-7 7',arrow:'M5 12h14 M13 6l6 6-6 6',plus:'M12 5v14 M5 12h14',download:'M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4 M7 10l5 5 5-5 M12 15V3',clock:'M12 8v4l3 3 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',calendar:'M8 2v4 M16 2v4 M3 10h18 M5 4h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2',close:'M6 6l12 12 M18 6L6 18',menu:'M4 6h16 M4 12h16 M4 18h16',info:'M12 11v6 M12 7h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9 M10 21h4',lock:'M5 11h14v10H5z M8 11V7a4 4 0 0 1 8 0v4'};
function icon(name,size=17){return `<svg aria-hidden="true" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="${icons[name]||icons.grid}"/></svg>`}
const badge=(s,c='')=>`<span class="badge ${c}">${s}</span>`;
const btn=(text,action='',cls='')=>`<button class="btn ${cls}" type="button" ${action}>${text}</button>`;
const link=(text,route,cls='')=>`<a class="btn ${cls}" href="#${route}">${text}</a>`;
const metric=(label,value,note='',cls='',attrs='')=>`<${attrs?'button':'div'} class="metric ${cls}" ${attrs}><div class="metric-label">${label}</div><div class="metric-value num">${value}</div><div class="metric-note">${note}</div></${attrs?'button':'div'}>`;
const panel=(title,body,action='',sub='')=>`<section class="panel"><div class="panel-head"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${action}</div>${body}</section>`;
const note=(s,type='neutral')=>`<div class="notice ${type}">${s}</div>`;
const head=(title,sub,action='',eyebrow='')=>`<div class="page-head"><div>${eyebrow?`<div class="eyebrow">${eyebrow}</div>`:''}<h1 tabindex="-1">${title}</h1><p>${sub}</p></div><div class="actions">${action}</div></div>`;
const search=(id,placeholder)=>`<div class="search">${icon('search')}<input id="${id}" type="search" placeholder="${placeholder}" aria-label="${placeholder}"></div>`;
const table=(heads,rows)=>{
  const labels=heads.map(h=>String(h).replace(/<[^>]*>/g,'').trim());
  const body=rows.replace(/<tr([^>]*)>([\s\S]*?)<\/tr>/g,(_,attrs,cells)=>{let col=0;return '<tr'+attrs+'>'+cells.replace(/<td([^>]*)>/g,(_,a)=>'<td'+a+' data-label="'+esc(labels[col++]||'')+'">')+'</tr>';});
  return `<div class="table-scroll mobile-cards" tabindex="0" role="region" aria-label="데이터 표 · 모바일에서는 항목별 카드"><table><thead><tr>${heads.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table></div>`;
};
const empty=(t,p)=>`<div class="empty">${icon('search',26)}<h3>${t}</h3><p>${p}</p></div>`;
const tabs=(items,key,value)=>`<div class="tabs" aria-label="${key} 보기">${items.map(([id,label,count])=>`<button type="button" class="tab ${id===value?'active':''}" data-tab="${key}" data-value="${id}" aria-pressed="${id===value}">${label}${count!==undefined?`<span>${count}</span>`:''}</button>`).join('')}</div>`;
const statusNames={approved:'승인 완료',pending:'검토 대기',returned:'보완 요청',missing:'미제출',locked:'미공개'};
const statusSymbol={approved:'✓',pending:'◷',returned:'!',missing:'—',locked:'·'};
const statusColor={approved:'green',pending:'amber',returned:'red',missing:'',locked:''};
const names=['김서연','박지우','최민준','정하은','강시우','조유진','윤준호','임채원','한지훈','오세아','서다인','신유나','권태양'];
const members=names.map((name,i)=>({id:i+1,name,role:i===1?'매니저':[2,6].includes(i)?'MVP':'',phone:`010-****-${String(2301+i*173).slice(-4)}`,day:[8,1,12,8,1,5,2,10,3,12,1,15,5][i],active:![0,3,5,7,8].includes(i),last:[4,0,0,5,0,1,0,2,4,0,0,0,0][i],cells:Array.from({length:30},(_,j)=>j>=15?'locked':j>=[8,1,12,8,1,5,2,10,3,12,1,15,5][i]?'missing':(i+j)%9===0?'returned':(i+j)%5===0?'pending':'approved')}));
const titles=['클로드 기본 세팅 & 기초지식 학습하기','프로젝트 세팅 & 학습 + 기본 MCP 연동하기','RAG 기반 작업과 컨텍스트화 이해','클로드 필수 Skills 설치 및 이해','온보딩 채널 활용을 위한 인스타그램 운영','그라운딩의 시작, 나만의 옵시디언 만들기','옵시디언과 텔레그램 연동하기','반복 업무를 AI로 옮기기','나만의 프롬프트 만들기','첫 AI 에이전트와 협업하기','AI로 콘텐츠 초안 만들기','우리 브랜드 톤 잡기','이미지 AI 활용하기','콘텐츠 검수 기준 세우기','2주간의 실행 돌아보기','4주차 온보딩 영상 다시보기','내 업무 흐름 연결하기','영상 베리에이션 만들기','운영 대시보드 만들기','전체 업무 흐름 점검','반복 작업 자동화','슬랙 사무실 만들기','첫 루프 돌리기','시스템 출근, 피드백의 스킬화','전체 회의, 다음 주 계획','AI 검색 시대의 노출 전략','회사 준비 #1 기획하기','회사 준비 #2 만들기','회사 준비 #3 알리기','전체 복습'];
const missions=titles.map((title,i)=>({id:i+1,title,week:Math.floor(i/5)+1,published:i<15,type:i%5===0?'실습 + 자료':i%3===0?'영상 + 실습':'텍스트 + 실습',quiz:i%3===1?2:3}));
const reviewSeed=[[8,1,'pending'],[9,2,'returned'],[6,3,'pending'],[3,3,'pending'],[3,4,'approved'],[12,1,'approved'],[4,2,'returned'],[3,1,'pending'],[1,5,'approved'],[13,4,'pending'],[2,2,'approved'],[8,2,'returned'],[9,1,'approved'],[12,2,'approved'],[8,4,'pending'],[3,2,'pending'],[12,3,'approved'],[10,4,'approved'],[2,5,'pending'],[1,1,'pending']];
const reviews=reviewSeed.map(([member,day,status],i)=>({id:i+1,member,day,status,age:2+i*2,feedback:status==='returned'?'프로젝트 설정 화면이 누락되었습니다. 설정한 내용이 보이도록 첨부해 주세요.':'',checked:[false,false,false]}));
reviews.forEach(r=>{members[r.member-1].cells[r.day-1]=r.status;members[r.member-1].day=Math.max(members[r.member-1].day,r.day)});
const questions=[{id:1,member:12,day:5,title:'퀴즈 3번 문항의 정답이 이해되지 않습니다.',body:'실행과 검수 중 어떤 기준을 우선으로 봐야 하나요? 예시를 들어 설명 부탁드립니다.',answered:false},{id:2,member:8,day:8,title:'MCP 커넥터 연결에서 토큰은 어디서 발급받나요?',body:'연결 단계에서 토큰 입력창이 나오는데 발급 위치를 찾지 못했습니다.',answered:false},{id:3,member:11,day:1,title:'옵시디언 저장 경로는 나중에 바꿀 수 있나요?',body:'현재 개인 폴더를 선택했습니다.',answered:true},{id:4,member:4,day:4,title:'이미지 생성 결과가 자꾸 깨져서 나옵니다.',body:'프롬프트에 글자를 포함하면 깨지는 부분이 생깁니다.',answered:true}];
const state={route:'members',memberTab:'all',week:1,memberSearch:'',selected:new Set(),reviewTab:'pending',reviewSearch:'',reviewSort:'old',currentReview:null,missionTab:'missions',missionWeek:1,questionTab:'open',analyticsTab:'ads',campaign:'cold',settingsTab:'tracking',filterState:'',qSearch:'',adSearch:'',adSet:'all',version:'v4',editorDirty:false};
const routes={overview:['운영 홈','grid','01-admin-overview.html'],members:['회원 미션관리','users','02-member-missions.html'],reviews:['제출물 검토','check','03-submission-review.html'],missions:['미션·학습 콘텐츠','book','04-mission-content.html'],questions:['질문함','chat','05-question-inbox.html'],analytics:['랜딩 성과','chart','06-landing-analytics.html'],metrics:['실측 입력','edit','07-manual-metrics.html'],settings:['운영·트래킹 설정','settings','08-admin-settings.html']};
function scope(){return `<div class="scope"><div class="scope-icon">${icon('book')}</div><div><div class="scope-title">AI 온보딩 챌린지 · 1기</div><p>6주 · 30개 미션 · 예시 수강생 13명</p></div><span class="spacer"></span>${badge('진행 중','green')}<span class="meta scope-end">예시 기준일 2026.09.10 · KST</span>${btn('기수 선택 ▾','data-action="cohort"','small')}</div>`}
function nav(){return `<aside class="sidebar" id="sidebar"><a class="brand" href="#overview"><span class="brand-mark">b</span><span>brandyaction<small>EDU / ADMIN</small></span></a><div class="workspace-label"><span class="square">B</span>교육 운영 워크스페이스</div><nav aria-label="관리자 메뉴"><a href="#overview" class="nav-link ${state.route==='overview'?'active':''}">${icon('grid')}운영 홈</a><div class="nav-section">교육 운영</div>${['members','reviews','missions','questions'].map(r=>`<a href="#${r}" class="nav-link ${state.route===r?'active':''}" ${state.route===r?'aria-current="page"':''}>${icon(routes[r][1])}${routes[r][0]}${r==='reviews'?`<span class="nav-count">${reviews.filter(x=>x.status==='pending').length}</span>`:r==='questions'?`<span class="nav-count">${questions.filter(x=>!x.answered).length}</span>`:''}</a>`).join('')}<div class="nav-section">모집 성과</div>${['analytics','metrics'].map(r=>`<a href="#${r}" class="nav-link ${state.route===r?'active':''}">${icon(routes[r][1])}${routes[r][0]}</a>`).join('')}<div class="nav-section">관리</div><a href="#settings" class="nav-link ${state.route==='settings'?'active':''}">${icon('settings')}운영·트래킹 설정</a></nav><div class="sidebar-bottom"><div class="meta">기존 주문·환불 등 메뉴는 유지<br>이번 시안은 개편 영역만 표시</div><div class="profile"><span class="avatar">R</span><div><b>리키</b><div class="meta">운영 관리자</div></div></div></div></aside>`}
function layout(){const route=routes[state.route]||routes.members;document.title=`${route[0]} | BrandyAction Edu 관리자 UIUX`;$('#root').innerHTML=nav()+`<div class="app"><header class="topbar"><div class="crumb">${btn(icon('menu'),'data-action="menu" aria-label="메뉴 열기"','iconbtn ghost mobile-menu')}<span class="crumb-root">관리자</span><span class="crumb-root">/</span><span>${route[0]}</span></div><div class="topright"><span class="meta">외부 연결 없음 · 새로고침 시 초기화</span><span class="design-tag">UIUX 시안 · 예시 데이터</span><a class="btn iconbtn ghost" href="#questions" aria-label="미답변 질문 보기">${icon('bell')}</a><span class="avatar">R</span></div></header><main id="main" class="content">${views[state.route]()}<div class="preview-note">DESIGN REVIEW · 표·숫자·회원·답변은 화면 검토용 예시입니다. 승인·저장·발송·추적·다운로드는 실제 서비스에 반영되지 않습니다.</div></main></div>`;}
function overview(){const pending=reviews.filter(x=>x.status==='pending').length;const late=members.filter(x=>x.last>=3).length;return head('오늘의 운영','먼저 처리할 검토와 참여 상태를 한눈에 확인하세요.',link('검토 시작하기 '+icon('arrow'),'reviews','primary'),'OPERATIONS')+scope()+`<div class="metrics">${metric('검토 대기',pending+'<small>건</small>','오래 기다린 제출물부터 확인','highlight','data-go="reviews"')}${metric('미답변 질문',questions.filter(x=>!x.answered).length+'<small>건</small>','답변이 필요한 학습 질문','','data-go="questions"')}${metric('활동 확인 필요',late+'<small>명</small>','3일 이상 미접속 · 원인 확인 필요','','data-action="inactive"')}${metric('오늘 접속',members.filter(x=>x.active).length+'<small>명</small>','전체 예시 수강생 13명 중','','data-action="visitors"')}</div><div class="two-col"><div class="stack">${panel('지금 처리할 일',`<div class="task"><span class="task-icon">${icon('check')}</span><div><h3>미션 검토 대기 ${pending}건</h3><p>가장 오래된 제출물 · 김서연 / Day 1</p></div>${link('연속 검토','reviews','small')}</div><div class="task"><span class="task-icon">${icon('chat')}</span><div><h3>학습 질문 ${questions.filter(x=>!x.answered).length}건</h3><p>퀴즈 해설 · MCP 연결 단계</p></div>${link('답변하기','questions','small')}</div><div class="task"><span class="task-icon">${icon('users')}</span><div><h3>장기 미접속 회원 ${late}명</h3><p>진행 상태 확인 후 필요한 안내만 전달</p></div>${btn('회원 확인','data-action="inactive"','small')}</div>`)}${panel('미션 진행 현황',`<div class="panel-body">${[1,2,3].map(w=>{let n=members.filter(m=>m.cells.slice((w-1)*5,w*5).includes('approved')).length;return `<div class="mini-bar"><span>${w}주차</span><div class="progress"><span style="width:${n/13*100}%"></span></div><b>${n}명</b></div>`}).join('')}<p class="meta">해당 주차에 1개 이상 승인된 회원 수 · 13명 기준</p></div>`,link('현황표 보기','members','small'))}</div><div class="stack">${panel('모집 성과 바로가기',`<div class="panel-body"><span class="badge outline">무료 라이브 · 09.28</span><h3 class="mt16">AI 직원을 둔<br>일당백 1인 회사 만들기</h3><p class="mt8" style="font-size:var(--type-small)">소재부터 CTA까지, 모집 과정의 이탈 지점을 확인합니다.</p><div class="divider"></div>${note('캠페인 시작 전입니다. 성과 화면의 숫자는 미래 실적이 아닌 디자인 예시입니다.')}${link('랜딩 성과 보기 '+icon('arrow'),'analytics','full mt16')}</div>`)}${panel('최근 검토 기록',`<div class="panel-body">${reviews.filter(x=>x.status==='approved').slice(0,3).map(r=>`<div class="activity-item"><span class="dot"></span><div><b>${members[r.member-1].name}</b> · Day ${r.day} 승인<div class="meta">운영자 리키 · 예시 기록</div></div></div>`).join('')}</div>`)}</div></div>`;}
function memberRows(){let filtered=members.filter(m=>(!state.memberSearch||(m.name+m.phone).includes(state.memberSearch))&&(state.memberTab==='all'||state.memberTab==='inactive'&&m.last>=3||state.memberTab==='today'&&m.active||state.memberTab==='pending'&&reviews.some(r=>r.member===m.id&&r.status==='pending')));if(!filtered.length)return empty('검색 결과가 없습니다.','이름·전화번호 뒷자리 또는 상태 필터를 확인하세요.');let start=(state.week-1)*5;return table([`<input type="checkbox" data-action="select-all" aria-label="검색된 회원 전체 선택" ${filtered.every(m=>state.selected.has(m.id))?'checked':''}>`,'회원',`현재 진행`,...Array.from({length:5},(_,i)=>`Day ${start+i+1}`),'전체 승인','최근 접속','관리'],filtered.map(m=>`<tr><td><input type="checkbox" data-member-select="${m.id}" aria-label="${m.name} 선택" ${state.selected.has(m.id)?'checked':''}></td><td><div class="person"><span class="avatar">${m.name.slice(0,1)}</span><div><button data-member="${m.id}">${m.name}</button>${m.role?`<span class="tag-role">${m.role}</span>`:''}<small>${m.phone}</small></div></div></td><td>Day ${m.day}<p>Lv${m.day>10?'3 성장':m.day>3?'2 실행':'1 시작'}</p></td>${m.cells.slice(start,start+5).map((s,j)=>`<td><button class="status-cell ${s}" data-cell-member="${m.id}" data-day="${start+j+1}" aria-label="${m.name}, Day ${start+j+1}, ${statusNames[s]}" title="${statusNames[s]}">${statusSymbol[s]}</button></td>`).join('')}<td><b class="num">${m.cells.filter(s=>s==='approved').length}</b><span class="muted"> / 30</span><div class="progress green"><span style="width:${m.cells.filter(s=>s==='approved').length/30*100}%"></span></div></td><td>${m.last===0?'오늘':m.last+'일 전'}${m.last>=3?`<p class="red">활동 확인 필요</p>`:''}</td><td>${btn('상세 '+icon('chevron',13),`data-member="${m.id}"`,'small')}</td></tr>`).join(''))+`<div class="table-foot"><span>조건에 맞는 ${filtered.length}명 / 예시 회원 13명</span><span>행 선택 → 대상 확인 → 안내 작성</span></div>`;}
function membersView(){const count=members.filter(m=>reviews.some(r=>r.member===m.id&&r.status==='pending')).length;return head('회원 미션관리','회원의 진행 상태를 비교하고, 미션 셀에서 바로 제출물을 확인하세요.',btn(icon('download')+' 명단 내보내기','data-demo="명단 내보내기 UI입니다. 실제 회원 데이터는 내려받지 않습니다."'),'LEARNER OPERATIONS')+scope()+`<div class="metrics">${metric('전체 회원','13<small>명</small>','선택한 기수 기준')}${metric('검토 대기 회원',count+'<small>명</small>','검토 대기 제출물이 있는 회원','highlight','data-member-tab="pending"')}${metric('활동 확인 필요','3<small>명</small>','3일 이상 미접속','','data-member-tab="inactive"')}${metric('오늘 접속','8<small>명</small>','접속 시점과 미션 상태 함께 확인','','data-member-tab="today"')}</div>${tabs([['all','전체 회원',13],['pending','검토 대기',count],['inactive','활동 확인 필요',3],['today','오늘 방문',8]],'memberTab',state.memberTab)}<section class="panel"><div class="toolbar inset">${search('member-search','이름 · 전화번호 뒷자리 검색')}<span class="spacer"></span><label class="row" style="font-size:var(--type-small)"><span class="muted">현황 주차</span><select id="member-week" aria-label="미션 현황 주차">${[1,2,3,4,5,6].map(w=>`<option value="${w}" ${w===state.week?'selected':''}>${w}주차 · Day ${w*5-4}–${w*5}</option>`).join('')}</select></label></div><div id="bulk-area">${bulkBar()}</div><div id="member-table">${memberRows()}</div></section><div class="spread mt16" style="flex-wrap:wrap"><div class="legend">${Object.keys(statusNames).map(s=>`<span><i class="status-cell ${s}">${statusSymbol[s]}</i>${statusNames[s]}</span>`).join('')}</div><span class="meta">승인 수와 제출 수는 별도로 관리합니다.</span></div>`;}
function bulkBar(){return state.selected.size?`<div class="bulk"><b>${state.selected.size}명 선택</b>${btn('선택 회원에게 안내','data-action="bulk-message"','small')}${btn('선택 해제','data-action="clear-selection"','small ghost')}<span class="meta desktop-only">발송 전 대상과 내용을 확인합니다.</span></div>`:'';}
function filteredReviews(){return reviews.filter(r=>(state.reviewTab==='all'||r.status===state.reviewTab)&&(!state.reviewSearch||(members[r.member-1].name+' '+titles[r.day-1]).includes(state.reviewSearch))).sort((a,b)=>state.reviewSort==='new'?a.age-b.age:b.age-a.age);}
function reviewView(){let rs=filteredReviews();if(!rs.some(r=>r.id===state.currentReview))state.currentReview=rs[0]?.id||null;return head('제출물 검토','목록을 유지한 채 답변을 확인하고, 승인 후 다음 제출물로 이어갑니다.',btn('검토 기준','data-action="review-guide"'),'REVIEW QUEUE')+scope()+tabs([['pending','검토 대기',reviews.filter(r=>r.status==='pending').length],['returned','보완 요청',reviews.filter(r=>r.status==='returned').length],['approved','승인 완료',reviews.filter(r=>r.status==='approved').length],['all','전체',reviews.length]],'reviewTab',state.reviewTab)+`<div class="toolbar">${search('review-search','회원명 · 미션명 검색')}<span class="spacer"></span><select id="review-sort" aria-label="제출물 정렬"><option value="old" ${state.reviewSort==='old'?'selected':''}>오래 기다린 순</option><option value="new" ${state.reviewSort==='new'?'selected':''}>최근 제출순</option></select></div><div id="review-content">${reviewContent()}</div>`;}
function reviewContent(){let rs=filteredReviews();if(!rs.length)return `<div class="panel">${empty('해당 상태의 제출물이 없습니다.','다른 상태를 선택하거나 검색어를 지워 보세요.')}</div>`;if(!rs.some(r=>r.id===state.currentReview))state.currentReview=rs[0].id;const r=reviews.find(x=>x.id===state.currentReview),m=members[r.member-1];return `<div class="review-shell"><aside class="queue" aria-label="제출물 목록"><div class="queue-title">${rs.length}건 · ${state.reviewSort==='old'?'오래 기다린 순':'최근 제출순'}</div>${rs.map(x=>`<button class="queue-item ${x.id===r.id?'active':''}" data-review="${x.id}" aria-pressed="${x.id===r.id}"><div class="spread"><strong>${members[x.member-1].name}</strong><span class="meta">Day ${x.day}</span></div><p>${esc(titles[x.day-1])}</p><div class="spread">${badge(statusNames[x.status],statusColor[x.status])}<small>${x.age}시간 전</small></div></button>`).join('')}</aside><section class="review-main"><div class="review-heading"><div class="spread"><div class="row"><span class="avatar">${m.name[0]}</span><b>${m.name}</b>${badge('Day '+r.day)}${badge(statusNames[r.status],statusColor[r.status])}</div>${btn('회원 상세',`data-member="${m.id}"`,'small ghost')}</div><h2>${esc(titles[r.day-1])}</h2><p class="meta mt8">제출 ${r.age}시간 전 · ${r.status==='returned'?'1차 제출 · 보완 대기':'1차 제출'} · 제출 당시 미션 v1</p></div><div class="review-grid"><div class="answers"><details class="guide"><summary>미션 안내와 제출 기준 보기</summary><p>실제로 운영하거나 학습 중인 브랜드를 기준으로 프로젝트를 설정하고, 적용 과정과 결과를 남겨 주세요. 브랜드명·작업 과정·결과 증빙을 확인합니다.</p></details><div class="answer-block"><label>01. 이번 미션을 적용한 브랜드와 업무</label><div class="answer-copy">동네에서 운영하는 베이커리 브랜드에 적용했습니다.\n매주 인스타그램 게시물을 준비하는 과정에서 반복되는 기획과 초안 작성을 정리했습니다.</div></div><div class="answer-block"><label>02. 직접 실행한 내용과 결과</label><div class="answer-copy">브랜드 소개, 고객 특징, 기존 게시물 예시를 프로젝트 자료로 정리했습니다.\n이 자료를 바탕으로 이번 주 게시물의 주제 3개와 초안을 만들고, 매장에서 실제로 제공하지 않는 내용은 직접 수정했습니다.</div></div><div class="answer-block"><label>03. 제출 파일 · 결과 증빙</label><div class="file-item"><span class="file-icon">PNG</span><div><b>프로젝트_설정_화면.png</b><div class="meta">첨부 파일 UI 예시 · 원본 파일 미연결</div></div>${btn('확인','data-action="file-preview"','small')}</div></div><div class="spread"><h3>멘토 피드백</h3>${btn('문구 불러오기','data-action="feedback-template"','small ghost')}</div><textarea id="review-feedback" rows="4" class="mt8" placeholder="잘한 점과 보완할 점을 구체적으로 남겨 주세요." aria-label="멘토 피드백">${esc(r.feedback)}</textarea><p class="meta mt8">보완 요청 시 사유가 필요합니다. 피드백만 저장하면 검토 상태는 바뀌지 않습니다.</p></div><aside class="inspector"><h3>승인 전 확인</h3><div class="review-checks">${['필수 답변이 모두 작성됨','실행 결과와 증빙이 일치함','미션의 완료 기준을 충족함'].map((t,i)=>`<label class="checkline"><input type="checkbox" data-review-check="${i}" ${r.checked[i]?'checked':''}><span>${t}</span></label>`).join('')}</div><div class="divider"></div><h3>학습 맥락</h3><div class="setting-line"><span>현재 진행</span><b>Day ${m.day}</b></div><div class="setting-line"><span>전체 미션 승인</span><b>${m.cells.filter(x=>x==='approved').length} / 30</b></div><div class="setting-line"><span>최근 접속</span><b>${m.last?m.last+'일 전':'오늘'}</b></div><div class="mini-timeline"><div><b>제출 접수</b>${r.age}시간 전 · 회원 제출</div><div><b>${r.status==='returned'?'보완 요청':r.status==='approved'?'승인 완료':'검토 대기'}</b>${r.status==='pending'?'아직 검토 기록이 없습니다.':'운영자 리키 · 예시 이력'}</div></div>${note('원문 안내는 접어 두고, 회원이 작성한 답변을 먼저 확인합니다.')}</aside></div><div class="review-actions"><p>검토 결과는 이 시안 안에서만 변경됩니다.</p>${btn('피드백만 저장','data-action="save-feedback"','small')}${btn('보완 요청','data-action="return-review"','danger')}${r.status!=='approved'?btn('승인 후 다음 '+icon('arrow',15),'data-action="approve-review"','primary'):btn('다음 제출물','data-action="next-review"','primary')}</div></section></div>`;}
function missionView(){let list=missions.filter(m=>m.week===state.missionWeek);return head('미션·학습 콘텐츠','주차별 미션을 구성하고, 학습 자료와 반복 챌린지를 연결합니다.',btn(icon('plus')+' 미션 등록','data-edit-mission="new"','primary'),'CURRICULUM')+scope()+tabs([['missions','일차별 미션',30],['learning','학습 콘텐츠',30],['ongoing','상시 챌린지',2]],'missionTab',state.missionTab)+(state.missionTab==='missions'?`<div class="spread"><div class="row wrap">${[1,2,3,4,5,6].map(w=>`<button class="pill ${state.missionWeek===w?'active':''}" data-mission-week="${w}">${w}주차 <span class="meta">5</span></button>`).join('')}</div><span class="meta desktop-only">공개 15 · 비공개 15</span></div><section class="week-card"><div class="spread week-head"><div class="row"><span class="week-label">WEEK ${state.missionWeek}</span><strong>${['AI 업무 환경 만들기','업무에 적용하기','콘텐츠 만들기','업무 연결하기','자동화 운영하기','사업으로 확장하기'][state.missionWeek-1]}</strong></div>${btn('+ 이 주차에 미션 추가','data-edit-mission="new"','small')}</div><p class="meta mb16">순서 이동 버튼으로 배치를 확인할 수 있습니다. 미션 제목을 누르면 편집 화면이 열립니다.</p>${list.map((m,i)=>`<div class="mission-row"><span class="draghandle" aria-hidden="true">≡</span><span class="day-no">${String(m.id).padStart(2,'0')}</span><div class="mission-copy"><button class="btn ghost" style="padding:0;min-height:0;white-space:normal;text-align:left;justify-content:flex-start" data-edit-mission="${m.id}"><strong>${esc(m.title)}</strong></button><p>${m.type} · 확인 퀴즈 ${m.quiz}문항 · 관리자 승인</p></div>${badge(m.published?'공개':'비공개',m.published?'green':'')}<span class="meta">완료 ${members.filter(x=>x.cells[m.id-1]==='approved').length} · 대기 ${members.filter(x=>x.cells[m.id-1]==='pending').length}</span><div class="row mission-actions">${btn('↑',`data-move="${m.id}" data-direction="-1" aria-label="Day ${m.id} 위로 이동" ${i===0?'disabled':''}`,'small')}${btn('↓',`data-move="${m.id}" data-direction="1" aria-label="Day ${m.id} 아래로 이동" ${i===list.length-1?'disabled':''}`,'small')}${btn('편집',`data-edit-mission="${m.id}"`,'small')}</div></div>`).join('')}</section><div class="mt16">${note('콘텐츠 편집과 회원 승인 업무는 분리합니다. 작성된 제출물에는 제출 당시 콘텐츠 버전을 유지하는 설계입니다.')}</div>`:state.missionTab==='learning'?panel('학습 콘텐츠',table(['일차','제목','형식','퀴즈','공개 상태','관리'],['Claude란 무엇인가','모델 선택하기','대화 컨텍스트 작동 방식','Context Window 이해하기','주요 활용 사례 탐색'].map((t,i)=>`<tr><td>Day ${i+1}</td><td><b>${t}</b><p>일차별 실습 전 기본 개념 학습</p></td><td>영상 + 텍스트</td><td>3문항</td><td>${badge('공개','green')}</td><td>${btn('편집',`data-edit-learning="${i+1}"`,'small')}</td></tr>`).join(''))+`<div class="table-foot">30개 중 1주차 대표 콘텐츠 5개 표시</div>`,btn('+ 학습 추가','data-edit-learning="new"','small')):`<div class="equal-col">${['오늘의 마케팅 실행','AI 업무 개선 기록'].map((t,i)=>panel(t,`<div class="panel-body"><div class="row">${badge('상시 운영','green')}${badge('매일 반복')}</div><p class="mt16" style="font-size:var(--type-small)">정규 일차 미션과 별도로 실행 내용을 기록합니다.</p><div class="metrics mt16" style="grid-template-columns:1fr 1fr;margin-bottom:0">${metric('참여 회원',i?'3명':'5명')}${metric('누적 완료',i?'2회':'3회')}</div><div class="row mt16">${btn('제출 답변 보기',`data-ongoing="${i}"`)}${btn('편집',`data-edit-ongoing="${i}"`,'ghost')}</div></div>`)).join('')}</div>`);}
function questionsView(){let qs=questions.filter(q=>(state.questionTab==='all'||state.questionTab==='open'&&!q.answered||state.questionTab==='done'&&q.answered)&&(!state.qSearch||(q.title+members[q.member-1].name).includes(state.qSearch)));return head('질문함','질문과 회원의 미션 맥락을 함께 확인하고 답변합니다.','','LEARNING SUPPORT')+scope()+tabs([['open','미답변',questions.filter(x=>!x.answered).length],['done','답변 완료',questions.filter(x=>x.answered).length],['all','전체',questions.length]],'questionTab',state.questionTab)+`<div class="toolbar">${search('question-search','질문 내용 · 회원명 검색')}<span class="spacer"></span><span class="meta">미답변 우선 · 답변 게시 전 검토</span></div><div id="question-list" class="stack">${qs.length?qs.map(q=>`<article class="panel"><div class="question-body"><div class="question-meta">${badge('Day '+q.day,'blue')}<button class="btn ghost small" data-member="${q.member}">${members[q.member-1].name}</button>${badge(q.answered?'답변 완료':'미답변',q.answered?'green':'amber')}<time>09.10 09:20 · 예시</time></div><h3 class="mt16">${q.title}</h3><p>${q.body}</p>${q.answered?`<div class="question-reply"><b>리키 · 운영자</b><p>${esc(q.reply||'상황을 확인했습니다. 해당 설정 화면에서 경로와 입력값을 먼저 확인해 주세요. 안내된 과정을 다시 실행한 뒤 결과를 남겨 주세요.')}</p></div>`:''}<div class="row mt16">${btn(q.answered?'답변 수정':'답변하기',`data-question="${q.id}"`,q.answered?'':'primary')}${btn('회원 미션 보기',`data-member="${q.member}"`,'ghost')}</div></div></article>`).join(''):empty('조건에 맞는 질문이 없습니다.','검색어 또는 상태를 변경해 보세요.')}</div>`;}

const adData={cold:[['제이_A_직원 없이 운영','A_메인',1800,162,50000,2050,18,'커리큘럼',true],['제이_A_혼자 하는 마케팅','A_메인',1100,77,40000,1300,25,'문제 공감',true],['윤익_A_AI 직원 만들기','A_메인',900,81,30000,1050,19,'무료 자료',true],['윤익_B_업무 시스템','B',600,42,20000,700,22,'강의 효과',true],['제이_B_비주얼 변형','B',240,12,14000,300,30,'첫 화면',true],['제이_A_초기 카피','A_메인',160,10,6000,200,31,'첫 화면',false]],warm:[['리타겟_R_이번엔 실행','R',600,96,15000,700,9,'강사 소개',true],['리타겟_R_마감 안내','R',400,60,10000,450,10,'무료 자료',true],['리타겟_R_자료 미리보기','R',140,18,5000,180,14,'커리큘럼',true],['리타겟_R_수정 카피','R',60,6,2000,70,15,'강의 효과',false]]};
const n=x=>Number(x).toLocaleString('ko-KR');const pct=(a,b)=>b?(100*a/b).toFixed(1)+'%':'—';
function adRows(){return adData[state.campaign].filter(x=>(state.adSet==='all'||x[1]===state.adSet)&&(!state.adSearch||x[0].includes(state.adSearch)));}
function analyticsScope(){return `<div class="scope"><div class="scope-icon">${icon('chart')}</div><div><div class="scope-title">AI 직원을 둔 일당백 1인 회사 만들기</div><p>무료 라이브 · 09.28 21:00 · 카카오 오픈채팅 연결</p></div><span class="spacer"></span>${badge('성과 데이터 예시','outline')}</div><div class="filter-stack"><div class="row wrap"><label>조회 기간 · KST<div class="row"><input id="analytics-from" aria-label="조회 시작일" type="date" value="2026-09-14"><span>–</span><input id="analytics-to" aria-label="조회 종료일" type="date" value="2026-09-28"></div></label><label>캠페인<select id="campaign"><option value="cold" ${state.campaign==='cold'?'selected':''}>콜드 · 신규 고객</option><option value="warm" ${state.campaign==='warm'?'selected':''}>리타겟 · 재방문 고객</option></select></label><label>광고세트<select id="ad-set"><option value="all">전체 광고세트</option>${[...new Set(adData[state.campaign].map(x=>x[1]))].map(s=>`<option value="${s}" ${s===state.adSet?'selected':''}>${s}</option>`).join('')}</select></label><label>구성 버전<select id="layout-version"><option value="v4" ${state.version==='v4'?'selected':''}>v4 · 09.22 적용</option><option value="v3" ${state.version==='v3'?'selected':''}>v3 · 09.17 적용</option></select></label><span class="spacer"></span>${btn('기간 적용','data-action="analytics-date"','small')}</div><div class="meta mt8">광고 성과는 콜드·리타겟을 분리해 조회합니다. 구성 버전별 집계는 합산하지 않습니다. 현재 표시값은 선택 상태를 설명하는 예시입니다.</div></div>`;}
function funnelView(){let steps=[['노출','192,000','메타 · 수동 예시','—'],['링크 클릭','7,000','메타 · 수동 예시','CTR 3.65%'],['랜딩 세션','6,600','자동 수집','광고 6,000 + 비광고 600'],['CTA 클릭','608','자동 수집','세션 대비 9.2%'],['카톡 입장','460','수동 · 누적','클릭 대비 75.7%*'],['라이브 참석','—','수동 · 최대 동시시청','집계 전'],['결제','—','수동 · 결제 건수','집계 전']];return panel('전체 모집 퍼널',`<div class="funnel">${steps.map(([t,v,s,c])=>`<div class="funnel-step"><div class="funnel-label">${t}</div><div class="value num">${v}</div><small>${s}</small><div class="conversion">${c}</div></div>`).join('')}</div><div class="panel-body" style="padding-top:0"><div class="meta">전체 캠페인·전체 버전 기준의 별도 요약입니다. *클릭→입장 비율은 동일인을 연결한 전환율이 아닌 집계값 비교입니다. 최대 동시시청도 고유 참석자 수와 다릅니다.</div></div>`,link('실측 입력','metrics','small'),'이 요약은 아래 광고 필터와 분리됩니다. · 모두 디자인 예시');}
function analyticsView(){let rows=adRows(),ss=rows.reduce((a,x)=>a+x[2],0),cc=rows.reduce((a,x)=>a+x[3],0),ll=rows.reduce((a,x)=>a+x[5],0);return head('랜딩 성과','어떤 소재가 클릭으로 이어졌고, 어느 섹션에서 멈췄는지 확인합니다.',link(icon('settings')+' 측정 설정','settings'),'ACQUISITION')+funnelView()+`<div class="mt24"></div>`+analyticsScope()+`${state.version==='v3'?note('v3를 선택했습니다. 이 HTML의 광고 집계 표는 v4 대표 예시로 유지되며, 실제 버전별 비교 화면은 ‘섹션·버전 비교’ 탭에서 확인할 수 있습니다.','warning'):''}<div class="metrics">${metric('광고 유입 세션',n(ss),'선택 캠페인·광고세트의 예시 합계')}${metric('CTA 클릭',n(cc),'실제 카톡 입장 수와 다릅니다.','highlight')}${metric('CTA 클릭률',pct(cc,ss),'CTA 클릭 / 랜딩 세션')}${metric('링크 클릭 대비 세션 차이',pct(ll-ss,ll),'경고 기준 초기값 30% · 원인 별도 확인')}</div>${tabs([['ads','소재 성과'],['sections','섹션·버전 비교'],['cta','CTA·환경'],['trend','일자별 추이']],'analyticsTab',state.analyticsTab)}${state.analyticsTab==='ads'?adsView():state.analyticsTab==='sections'?sectionsView():state.analyticsTab==='cta'?ctaView():trendView()}`;}
function adsView(){let rows=adRows(),sets=[...new Set(rows.map(x=>x[1]))];return `<div class="stack">${panel('광고세트별 요약',table(['광고세트','세션','CTA 클릭','CTA 클릭률','첫 화면 이탈률*'],sets.map(s=>{let rr=rows.filter(x=>x[1]===s),a=rr.reduce((v,x)=>v+x[2],0),b=rr.reduce((v,x)=>v+x[3],0);return `<tr><td><b>${s}</b></td><td>${n(a)}</td><td>${n(b)}</td><td><b>${pct(b,a)}</b></td><td>${a?(rr.reduce((v,x)=>v+x[2]*x[6],0)/a).toFixed(1):'0'}%</td></tr>`}).join('')),badge(state.campaign==='cold'?'콜드 캠페인':'리타겟 캠페인','outline'))}<section class="panel"><div class="panel-head"><div><h2>소재별 성과</h2><p>운영 중단 소재도 과거 성과를 유지합니다.</p></div>${btn('내보내기','data-demo="소재별 성과 CSV 내보내기 UI입니다. 실제 데이터 연결 전입니다."','small')}</div><div class="toolbar inset">${search('ad-search','소재명 검색')}<span class="spacer"></span><span class="meta">표본 300세션 · 위너 검토 30클릭 기준</span></div><div id="ads-table">${adsTable()}</div></section>${note('*‘첫 화면 이탈’은 CTA 클릭이 없고 가장 깊은 도달 섹션이 첫 화면인 세션의 근사 지표입니다. 실제 무스크롤·무터치를 확정하는 지표는 아닙니다.')}<div class="equal-col">${panel('광고 외 유입',table(['유입','세션','CTA 클릭','클릭률'],`<tr><td>직접 유입</td><td>400</td><td>32</td><td>8.0%</td></tr><tr><td>기타 참조</td><td>200</td><td>12</td><td>6.0%</td></tr>`),'','전체 기간·전체 버전 별도 예시 · 광고 표와 합산하지 않음')}${panel('자동 판정 상태',`<div class="panel-body">${badge('판정 설정 대기','amber')}<h3 class="mt16">랜딩 클릭률 하한이 아직 없습니다.</h3><p class="mt8" style="font-size:var(--type-small)">자동 경고는 메타 수치 연결과 기준 설정 후 사용합니다. 낮은 성과만으로 소재·랜딩 문제를 확정하지 않습니다.</p>${btn('판정 기준 설정','data-action="criteria"','small mt16')}</div>`)}</div></div>`;}
function adsTable(){let rows=adRows();return rows.length?table(['소재명','광고세트','세션','CTA 클릭','클릭률','메타 CTR','최다 이탈','판정'],rows.map(x=>`<tr><td><b>${x[0]}</b><p>${x[8]?'운영 중':'운영 중단 · 기록 유지'}</p></td><td>${x[1]}</td><td>${n(x[2])}</td><td><b>${x[3]}</b></td><td>${pct(x[3],x[2])}</td><td>${pct(x[5],x[4])}</td><td>${x[7]}</td><td>${x[2]<300?badge('표본 부족 · 보류'):x[3]>=30?badge('위너 검토 가능','green'):badge('추가 관찰','amber')}</td></tr>`).join(''))+`<div class="table-foot"><span>${rows.length}개 소재 · 한글 소재명 표시</span><span>‘위너 검토 가능’은 자동 선정이 아닙니다.</span></div>`:empty('소재가 없습니다.','소재명 또는 광고세트를 확인해 주세요.');}
function sectionsView(){let sections=['첫 화면','문제 공감','강의 효과','커리큘럼','무료 자료','강사 소개','참여 안내','최종 CTA'];let v3=[100,72,61,45,36,29,24,19],v4=[100,79,68,55,44,35,29,24];return `<div class="stack">${note('비교 예시의 유입 조건: 콜드 / A_메인 / 제이_A_직원 없이 운영으로 고정했습니다. 상단 필터와 별도의 고정 비교 예시입니다. 위치가 바뀐 섹션은 내용 개선 효과와 구분해 해석하세요.')}<div class="equal-col">${panel('비교 기준',`<div class="panel-body"><div class="field-row"><label class="field">변경 전<select aria-label="변경 전 버전" data-demo-select><option>v3 · 09.17–09.21</option></select></label><label class="field">변경 후<select aria-label="변경 후 버전" data-demo-select><option>v4 · 09.22–09.28</option></select></label></div><div class="row wrap">${badge('콜드')}${badge('A_메인')}${badge('제이_A_직원 없이 운영')}</div><p class="meta mt16">v3 800세션 / v4 1,800세션 · 표본이 달라 인과관계 단정 불가</p></div>`)}${panel('구성 변경 기록',`<div class="panel-body"><div class="spread"><b>v4 · 09.22 10:00 KST</b>${badge('선택 버전','red')}</div><p style="font-size:var(--type-small)" class="mt8">강의 효과 카피 교체 · 무료 자료를 강사 소개 앞으로 이동</p><div class="divider"></div><label class="field">변경 메모<input id="version-note" value="강의 효과 카피 교체 · 무료 자료 위치 변경"></label>${btn('메모 저장','data-action="save-note"','small')}</div>`)}</div>${panel('같은 섹션, 변경 전후 비교',table(['섹션','v3 순서','v3 도달률','v4 순서','v4 도달률','변화','v4 이탈률*','평균 체류'],sections.map((s,i)=>`<tr><td><b>${s}</b></td><td>${i===4?'6':i===5?'5':i+1}</td><td>${v3[i]}%</td><td>${i+1}${i===4||i===5?' <span class="meta">위치 변경</span>':''}</td><td><b>${v4[i]}%</b></td><td class="${i?'green':''}">${i?'+'+(v4[i]-v3[i])+'%p':'—'}</td><td>${i===0?'—':v4[i-1]-v4[i]+'%p'}</td><td>${[3.2,5.1,8.4,12.6,6.5,4.8,3.9,4.1][i]}초</td></tr>`).join(''))+`<div class="table-foot">*직전 섹션 대비 도달률 차이입니다. 섹션 자체에서 떠난 확정 이탈률과 구분합니다.</div>`)}${panel('소재 × 섹션 도달률',table(['v4 · 소재',...sections.slice(0,6)],adData[state.campaign].slice(0,3).map((a,k)=>`<tr><td>${a[0]}</td>${[100,79-k*5,68-k*5,55-k*7,44-k*5,35-k*6].map(v=>`<td><span class="heat" style="--heat:${v/3}%">${v}%</span></td>`).join('')}</tr>`).join(''))+`<div class="panel-body">${note('동일 랜딩에서 소재별 이탈 차이가 난다면, 소재가 만든 기대와 본문 내용의 차이부터 확인하세요. 버전별 섹션 순서를 따르고 서로 다른 버전의 표는 합치지 않습니다.')}</div>`,badge('v4 단독','outline'))}</div>`;}
function ctaView(){return `<div class="stack">${note('아래 CTA·환경 수치는 콜드 전체 / v4의 고정 예시입니다. 상단 광고세트 검색과는 별도로 화면 구조를 보여줍니다.')}<div class="equal-col">${panel('CTA 위치별 클릭',table(['버튼 위치','클릭 수','비중','평균 스크롤'],`<tr><td>첫 화면<p class="mono">hero_cta</p></td><td>54</td><td>14.1%</td><td>4%</td></tr><tr><td>하단 고정<p class="mono">sticky_cta</p></td><td>272</td><td>70.8%</td><td>52%</td></tr><tr><td>마지막 섹션<p class="mono">final_cta</p></td><td>58</td><td>15.1%</td><td>94%</td></tr>`))}${panel('클릭이 발생한 구간',`<div class="panel-body">${[['강의 효과',108],['커리큘럼',86],['무료 자료',50],['기타 섹션',28]].map(([s,v])=>`<div class="mini-bar" style="grid-template-columns:80px 1fr 40px"><span>${s}</span><div class="progress"><span style="width:${v/108*100}%"></span></div><b>${v}</b></div>`).join('')}<p class="meta">하단 고정 버튼 272회 · 클릭 시 보고 있던 섹션</p></div>`)}</div>${panel('카카오 이동 실패 의심',table(['브라우저','CTA 클릭','클릭 후 페이지 잔류','의심률','확인 상태'],[['Instagram 인앱',180,27],['Facebook 인앱',80,8],['Safari',70,2],['Chrome',54,1]].map(([t,a,b])=>`<tr><td><b>${t}</b></td><td>${a}</td><td>${b}</td><td class="${b/a>.1?'red':''}">${pct(b,a)}</td><td>${badge(b/a>.1?'이동 동작 확인 필요':'추세 관찰',b/a>.1?'amber':'')}</td></tr>`).join(''))+`<div class="panel-body">${note('5초 후 페이지가 보인다는 사실만으로 앱 이동 실패를 확정할 수 없습니다. 총 38 / 384 = 9.9%는 진단 신호이며 실제 오픈채팅 입장 테스트와 함께 확인합니다.','warning')}</div>`)}<div class="equal-col">${panel('디바이스 · 방문 유형',table(['구분','세션','CTA 클릭','클릭률'],`<tr><td>모바일</td><td>3,840</td><td>300</td><td>7.8%</td></tr><tr><td>데스크톱</td><td>960</td><td>84</td><td>8.8%</td></tr><tr><td>신규 방문</td><td>4,000</td><td>280</td><td>7.0%</td></tr><tr><td>재방문</td><td>800</td><td>104</td><td>13.0%</td></tr>`))}${panel('끝까지 읽고도 누르지 않은 방문',`<div class="panel-body"><div class="metric-value num">840<small> 세션</small></div><p class="mt8" style="font-size:var(--type-small)">마지막 섹션 도달 1,152세션 중 72.9%</p><div class="divider"></div><p style="font-size:var(--type-small)">전체 4,800세션 중 17.5%입니다. CTA 문구, 강의 날짜·형식·제공 혜택이 충분히 명확한지 검토합니다.</p><p class="meta mt16">별도 상태 설명 예시 · 실제 집계 시 클릭 세션과 클릭 이벤트 수를 구분해야 합니다.</p></div>`)}</div></div>`;}
function trendView(){let ses=[250,300,350,400,420,500,550,530,500,480,520],click=[5,6,6.5,7,7.2,8,8.2,7.8,8.5,9,9.5],exit=[31,29,28,26,25,23,22,23,22,21,20];function bars(vals,max){return `<div class="sparkbars">${vals.map((v,i)=>`<div class="spark-col">${i===7?`<span class="chart-annotation">v4 적용</span>`:''}<div class="bar ${i>=7?'accent':''}" style="height:${v/max*100}%" title="09.${i+15} · ${v}"></div><small>${i+15}</small></div>`).join('')}</div>`}return `<div class="stack">${note('콜드 / A_메인 고정 추이 예시 · 09.15–09.25 KST. 페이지 변경과 예산 변경이 함께 일어날 수 있으므로 그래프 변화만으로 원인을 단정하지 않습니다.')}<div class="trend-grid">${panel('랜딩 세션',`<div class="panel-body">${bars(ses,650)}<p class="meta mt16">단위: 세션 · 가로축: 9월 날짜</p></div>`)}${panel('CTA 클릭률',`<div class="panel-body">${bars(click,12)}<p class="meta mt16">단위: % · 가로축: 9월 날짜</p></div>`)}${panel('첫 화면 이탈률',`<div class="panel-body">${bars(exit,40)}<p class="meta mt16">단위: % · 가로축: 9월 날짜</p></div>`)}</div>${panel('일자별 원자료',table(['일자 · KST','세션','CTA 클릭률','첫 화면 이탈률','랜딩 버전','운영 메모'],ses.map((v,i)=>`<tr><td>2026.09.${i+15}</td><td>${v}</td><td>${click[i]}%</td><td>${exit[i]}%</td><td>${i>=7?'v4':'v3'}</td><td>${i===7?'무료 자료 위치 변경 · 신규 광고세트 등장':'—'}</td></tr>`).join('')))}</div>`;}
function manualView(){return head('실측 입력','자동 추적이 끊기는 카카오 입장 이후를 날짜별로 보완합니다.',link('전체 퍼널 보기','analytics'),'MANUAL MEASUREMENTS')+`<div class="scope"><div><b class="scope-title">일당백 무료 라이브 · 2026.09 캠페인</b><p>수기 입력은 랜딩 전체 기준입니다. 소재별 카카오 입장은 알 수 없습니다.</p></div></div><div class="settings-layout"><div class="stack">${panel('날짜별 실측 기록',`<form id="manual-form" class="panel-body"><div class="field-row"><label class="field">기준 날짜 · KST<input type="date" name="date" value="2026-09-22" required></label><label class="field">기록자<input value="리키 · 운영자" readonly></label></div><h3 class="mb16">메타 광고 수치</h3><div class="field-row"><label class="field">당일 노출<input type="number" name="impressions" min="0" step="1" placeholder="예: 24000"><small>전체 캠페인 합계 · 자동 연동 미연결 시 입력</small></label><label class="field">당일 링크 클릭<input type="number" name="clicks" min="0" step="1" placeholder="예: 840"></label></div><div class="field-row"><label class="field">카톡방 누적 입장 인원<input type="number" name="joins" min="0" step="1" value="460" required><small>날짜별 누적값은 합산하지 않고, 기간 마지막 값을 사용</small></label><label class="field">당일 퇴장 인원<input type="number" name="leaves" min="0" step="1" value="8"><small>현재 방 인원과 누적 입장 인원을 구분해 입력</small></label></div><div class="field-row"><label class="field">라이브 최대 동시시청<input type="number" name="live" min="0" step="1" placeholder="집계 전"><small>09.28 라이브 종료 후 입력 · 미집계는 빈칸</small></label><label class="field">당일 결제 건수<input type="number" name="payments" min="0" step="1" placeholder="집계 전"><small>누적 결제가 아닌 당일 완료 건수</small></label></div><label class="field">메모<textarea name="memo" rows="3" placeholder="집계 기준 또는 운영 특이사항을 남겨 주세요."></textarea></label><div class="notice neutral">아직 집계하지 않은 항목은 0이 아니라 빈칸으로 둡니다. 이 시안의 저장 버튼은 확인 화면만 표시합니다.</div><div class="row mt16"><span class="spacer"></span><button class="btn primary" type="submit">입력 내용 확인</button></div></form>`)}${panel('기록 내역',table(['일자 · KST','누적 입장','당일 퇴장','최대 동시시청','당일 결제','기록자'],`<tr><td>09.22</td><td>460</td><td>8</td><td>미집계</td><td>미집계</td><td>리키</td></tr><tr><td>09.21</td><td>392</td><td>3</td><td>미집계</td><td>미집계</td><td>리키</td></tr>`),'','기록 내역은 고정 예시입니다.')}</div><aside>${panel('입력 기준',`<div class="panel-body"><h3>자동과 수동을 구분합니다.</h3><p class="mt8" style="font-size:var(--type-small)">세션·CTA 클릭은 자동 수집, 카톡 입장·라이브·결제는 수동 기록입니다.</p><div class="divider"></div><h3>개인을 연결하지 않습니다.</h3><p class="mt8" style="font-size:var(--type-small)">익명 랜딩 방문자를 회원의 미션 진행 기록과 합치지 않습니다.</p><div class="divider"></div><h3>시간대는 KST입니다.</h3><p class="mt8" style="font-size:var(--type-small)">입력·표시 모두 한국 시간으로 통일합니다.</p></div>`)}</aside></div>`;}
function settingsView(){return head('운영·트래킹 설정','교육 운영 규칙과 광고 측정 설정을 구분해 관리합니다.','','ADMIN SETTINGS')+tabs([['tracking','픽셀·이벤트'],['criteria','판정 기준'],['operations','교육 운영']],'settingsTab',state.settingsTab)+(state.settingsTab==='tracking'?trackingView():state.settingsTab==='criteria'?criteriaView():operationsView());}
function trackingView(){return `<div class="settings-layout"><div class="stack">${panel('메타 픽셀',`<div class="panel-body"><label class="switch"><input type="checkbox" id="pixel-enabled" checked>페이지 전체에 PageView 적용</label><label class="field mt24">Meta 픽셀 ID<input id="pixel-id" inputmode="numeric" placeholder="운영 픽셀 ID 전달 후 입력"><small>현재 미연결 · 이 시안에서는 픽셀 스크립트가 실행되지 않습니다.</small></label><div class="field-row"><label class="field">카카오 오픈채팅 목적지<input id="kakao-url" type="url" placeholder="실제 오픈채팅 URL 입력"><small>3개 CTA는 모두 동일 목적지를 사용합니다.</small></label><label class="field">이벤트 수집 기간<input readonly value="상시 수집 · 캠페인 기간과 독립"><small>09.14–09.28은 기본 조회 기간만 설정</small></label></div>${btn('저장·발행 미리보기','data-action="pixel-save"','primary')}</div>`,badge('미연결','amber'))}${panel('버튼별 이벤트 매핑',table(['위치','이벤트명','content_name'],[['hero_cta','hero'],['sticky_cta','sticky'],['final_cta','final']].map(([a,b])=>`<tr><td class="mono">${a}</td><td class="mono">CompleteRegistration</td><td class="mono">${b}</td></tr>`).join(''))+`<div class="panel-body">${note('이벤트명 1종으로 통일합니다. content_category에는 광고세트명(utm_term)이 자동으로 들어가는 설계입니다. 버튼 문구와 추적 식별자는 분리합니다.')}</div>`)}${panel('테스트 모드 · 발행 전 체크',`<div class="panel-body"><div class="row wrap"><span class="mono">?testmode=1</span>${btn('테스트 띠 미리보기','data-action="test-mode"','small')}<span class="meta">해제: ?testmode=0</span></div><p class="meta mt16">브라우저별로 별도 설정 · 내부 이벤트 저장과 픽셀을 모두 제외합니다.</p><div class="divider"></div>${['Instagram 인앱 → 카카오 입장','Facebook 인앱 → 카카오 입장','Safari → 카카오 입장','Chrome → 카카오 입장'].map(t=>`<div class="setting-line"><span>${t}</span>${badge('테스트 전','outline')}</div>`).join('')}<p class="meta mt16">HTML 디자인 시안에서 실제 앱 전환 테스트를 수행하지 않았습니다.</p></div>`)}</div><aside>${panel('설정 전 확인',`<div class="panel-body"><h3>전환 = CTA 클릭</h3><p class="mt8" style="font-size:var(--type-small)">메타 이벤트 이름이 CompleteRegistration이어도 실제 회원가입·입장 완료를 뜻하지 않습니다.</p><div class="divider"></div><h3>이중 집계 방지</h3><p class="mt8" style="font-size:var(--type-small)">별도의 버튼 글자 기반 이벤트 설정은 함께 사용하지 않습니다.</p><div class="divider"></div><h3>수집은 멈추지 않게</h3><p class="mt8" style="font-size:var(--type-small)">광고 일정은 조회 기본값입니다. 종료일 이후에도 수집하는 설계입니다.</p></div>`)}</aside></div>`;}
function criteriaView(){let fields=[['소재 판정 최소 세션 수',300,'건','minSessions'],['위너 검토 최소 CTA 클릭 수',30,'건','minClicks'],['랜딩 문제 의심 클릭률 하한','','%','landingRate'],['메타 링크 CTR 정상 하한',3,'%','metaCTR'],['카카오 이동 의심 판정 대기 시간',5,'초','wait'],['링크 클릭 대비 세션 차이 경고선',30,'%','gap']];return `<div class="settings-layout"><div class="stack">${panel('성과 판정 기준',`<form id="criteria-form" class="panel-body">${fields.map(([t,v,u,key])=>`<div class="setting-line"><div><b>${t}</b><p>${key==='landingRate'?'비워 두고 시작 · 운영 데이터 확인 후 설정':key==='wait'?'클릭 후 페이지에 남아 있는지 확인':'요청서의 참고 초기값 · 확정 기준 아님'}</p></div><label class="row"><input type="number" name="${key}" value="${v}" min="0" ${u==='%'?'max="100" step="0.1"':'step="1"'} aria-label="${t}" placeholder="미설정"><span>${u}</span></label></div>`).join('')}<div class="mt24">${note('빈 클릭률 하한을 0%로 취급하지 않습니다. 기준 미설정 상태에서는 랜딩 문제 경고를 내리지 않습니다.','warning')}</div><div class="row mt24"><span class="spacer"></span><button class="btn primary" type="submit">기준 저장 미리보기</button></div></form>`)}${panel('자동 감지 예시',`<div class="panel-body"><div class="row">${badge('설정 완료 후 활성화','outline')}</div><p class="mt16" style="font-size:var(--type-small)">메타 CTR 정상 + 랜딩 CTA 클릭률 하한 미만이면 ‘랜딩 문제 의심’을 표시합니다. 반대 경우에는 ‘소재 검토 필요’를 표시합니다.</p><p class="meta mt16">상관관계 기반 점검 신호입니다. 속도·인앱 환경·유입 품질 등을 함께 확인합니다.</p></div>`)}</div><aside>${panel('적용 방식',`<div class="panel-body"><h3>과거 데이터에도 적용</h3><p class="mt8" style="font-size:var(--type-small)">기준은 이벤트에 고정 저장하지 않고 조회할 때 적용하는 설계입니다.</p><div class="divider"></div><h3>경고는 진단 출발점</h3><p class="mt8" style="font-size:var(--type-small)">세션 차이가 크다고 로딩 속도 문제로 확정하지 않습니다. 추적 차단과 측정 기준도 점검합니다.</p></div>`)}</aside></div>`;}
function operationsView(){return `<div class="settings-layout"><div class="stack">${panel('미션 승인 · 공개 규칙',`<div class="panel-body"><label class="field">자동 승인 범위<select id="auto-approval"><option>자동 승인 없음 · 관리자 검토</option><option>1주차까지 자동 승인</option><option>2주차까지 자동 승인</option><option>3주차까지 자동 승인</option><option>6주차까지 자동 승인</option></select><small>자동 승인은 수동 검토 결과와 이력에서 구분합니다.</small></label><label class="field">다음 주차 공개<select><option>일정에 맞춰 공개</option><option>이전 주차 승인 완료 후 공개</option><option>관리자가 직접 공개</option></select></label>${note('주차 승인과 다음 주차 공개는 서로 다른 설정입니다. 규칙 변경이 기존 제출물에 영향을 주는지는 저장 전 확인합니다.','warning')}${btn('변경 영향 확인','data-action="approval-rule"','primary mt16')}</div>`)}${panel('공지 · 회원 역할',`<div class="panel-body"><label class="field">공지 배너<textarea rows="2" placeholder="회원에게 보일 공지. 비워 두면 숨김."></textarea></label><div class="field-row"><label class="field">MVP 표시<select><option>텍스트 배지로 표시</option><option>표시하지 않음</option></select></label><label class="field">기본 관리자 역할<input readonly value="운영 관리자 · 권한 연동 전"></label></div>${btn('미리보기','data-demo="공지와 역할 표시 설정 시안입니다. 회원 화면에는 반영되지 않습니다."')}</div>`)}${panel('접근 · 보안',`<div class="panel-body"><div class="setting-line"><div><b>관리자 인증</b><p>실제 서비스에서는 서버에서 접근 권한 검사</p></div>${badge('설계만 반영','outline')}</div><div class="setting-line"><div><b>관리자 비밀번호</b><p>기본 비밀번호나 원문을 화면에 노출하지 않음</p></div>${btn('변경','data-demo="비밀번호 변경 UI입니다. 이 HTML에는 인증 기능이 없습니다."','small')}</div><div class="setting-line"><div><b>개인정보 표시</b><p>회원 목록에서 연락처 마스킹 적용</p></div>${badge('마스킹','green')}</div></div>`)}</div><aside>${panel('범위 구분',`<div class="panel-body"><h3>교육 운영에 집중</h3><p class="mt8" style="font-size:var(--type-small)">기수·미션·질문·학습 활동을 관리합니다.</p><div class="divider"></div><h3>CRM은 기존 OS에서</h3><p class="mt8" style="font-size:var(--type-small)">자동 마케팅 발송과 LTV 예측을 이 화면에 추가하지 않습니다. 회원 안내는 발송 전 검토 흐름만 확인합니다.</p></div>`)}</aside></div>`;}
const views={overview,members:membersView,reviews:reviewView,missions:missionView,questions:questionsView,analytics:analyticsView,metrics:manualView,settings:settingsView};

let lastFocus=null;
function toast(message){const el=$('#toast');el.textContent=message;el.hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.hidden=true,4500);}
function showDialog(title,body,footer='',drawer=false){lastFocus=document.activeElement;const d=$('#dialog');if(d.open)d.close();d.className=drawer?'drawer':'';d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2>${btn(icon('close'),'data-action="close-dialog" aria-label="닫기"','iconbtn ghost')}</div><div class="dialog-body">${body}</div>${footer?`<div class="dialog-foot">${footer}</div>`:''}`;d.showModal();}
function closeDialog(){const d=$('#dialog');if(d.open)d.close();if(lastFocus&&lastFocus.isConnected)lastFocus.focus();}
function refresh(focusId){layout();for(const [id,v]of [['member-search',state.memberSearch],['review-search',state.reviewSearch],['ad-search',state.adSearch],['question-search',state.qSearch]]){const e=$('#'+id);if(e)e.value=v;}if(focusId){const e=$('#'+focusId);if(e){e.focus();try{e.setSelectionRange(e.value.length,e.value.length)}catch{}}}}
function go(route){closeDialog();if(location.hash.slice(1)===route){state.route=route;refresh();}else location.hash=route;}
function memberDialog(id){const m=members.find(x=>x.id===id);if(!m)return;const count=s=>m.cells.filter(x=>x===s).length;showDialog('회원 상세',`<div class="drawer-profile"><span class="avatar red">${m.name[0]}</span><div><h2>${m.name} ${m.role?badge(m.role):''}</h2><p>${m.phone} · member-${String(m.id).padStart(3,'0')}</p></div></div><div class="metrics">${metric('승인 완료',count('approved'))}${metric('검토 대기',count('pending'))}${metric('보완 요청',count('returned'))}</div><div class="spread"><b>미션 진행 이력</b><span class="meta">전체 30개 · 셀 클릭</span></div><div class="member-days">${m.cells.map((s,i)=>`<button class="status-cell ${s}" data-cell-member="${m.id}" data-day="${i+1}" aria-label="${m.name} Day ${i+1} ${statusNames[s]}"><span>Day ${i+1}</span><small>${statusNames[s]}</small></button>`).join('')}</div><div class="divider"></div><h3>운영 정보</h3><div class="setting-line"><span>현재 진행</span><b>Day ${m.day}</b></div><div class="setting-line"><span>마지막 접속</span><b>${m.last?m.last+'일 전':'오늘'}</b></div><div class="setting-line"><span>활동 상태</span>${badge(m.last>=3?'활동 확인 필요':'정상',m.last>=3?'amber':'green')}</div><label class="field mt24">운영 메모<textarea rows="3" id="member-note" placeholder="다음 운영자가 알아야 할 내용만 남겨 주세요.">${esc(m.note||'')}</textarea><small>내부 메모 · 회원에게 노출하지 않습니다.</small></label>${btn('메모 저장',`data-save-member-note="${m.id}"`,'small')}<div class="mt16">${note('이 회원 상세는 학습 관리용입니다. 익명 광고 방문자와 연결하지 않습니다.')}</div>`,btn('안내 작성',`data-message-member="${m.id}"`,'primary'),true);}
function cellDialog(memberId,day){const m=members[memberId-1],s=m.cells[day-1];const found=reviews.find(r=>r.member===memberId&&r.day===day);if(found){closeDialog();state.reviewTab=found.status;state.currentReview=found.id;state.reviewSearch='';go('reviews');return;}showDialog(`Day ${day} · ${m.name}`,`<h3>${esc(titles[day-1])}</h3><div class="mt16">${badge(statusNames[s],statusColor[s])}</div><p class="mt16" style="font-size:var(--type-small)">${s==='locked'?'아직 공개되지 않은 미션입니다.':s==='missing'?'제출된 답변이 없습니다. 회원의 진행 일정과 공개 범위를 먼저 확인하세요.':'상태 표시용 예시입니다. 이 셀의 상세 제출물 원문은 시안에 포함하지 않았습니다.'}</p>`,btn('회원 상세',`data-member="${memberId}"`)+btn('닫기','data-action="close-dialog"','primary'));}
function messageDialog(ids){const target=members.filter(m=>ids.includes(m.id));showDialog('회원 안내 작성',`<div class="notice neutral">교육 운영 안내의 검토 흐름입니다. 실제 메시지를 발송하지 않습니다.</div><h3 class="mt24">받는 사람 ${target.length}명</h3><div class="row wrap mt8">${target.map(m=>badge(m.name)).join('')}</div><label class="field mt24">안내 내용<textarea id="message-body" rows="5" placeholder="예: 이번 주 미션을 진행하며 어려운 점이 있다면 질문함에 남겨 주세요."></textarea></label><label class="field">발송 채널<select><option>연결 전 · 교육 운영 알림</option></select></label><p class="meta">자동 CRM 캠페인이나 실제 카카오 메시지 발송 기능은 포함하지 않습니다.</p>`,btn('취소','data-action="close-dialog"')+btn('안내 미리보기','data-action="preview-message"','primary'));}
function activeReview(){return reviews.find(x=>x.id===state.currentReview)}
function updateReview(status){const r=activeReview();if(!r)return;const feed=$('#review-feedback');if(feed)r.feedback=feed.value;if(status==='approved'&&!r.checked.every(Boolean)){toast('승인 전 확인 항목 3개를 모두 체크해 주세요.');return;}if(status==='returned'&&!r.feedback.trim()){toast('보완이 필요한 내용을 피드백에 작성해 주세요.');$('#review-feedback')?.focus();return;}const id=r.id;showDialog(status==='approved'?'승인 후 다음 제출물로 이동':'보완 요청 확인',`<h3>${members[r.member-1].name} · Day ${r.day}</h3><p class="mt8" style="font-size:var(--type-small)">${esc(titles[r.day-1])}</p><div class="divider"></div><p style="font-size:var(--type-small)">${status==='approved'?'이 제출물을 승인 완료로 바꾸고, 현재 목록의 다음 제출물을 엽니다.':'회원에게 전달할 보완 사유를 확인하세요.'}</p>${r.feedback?`<div class="answer-copy mt16">${esc(r.feedback)}</div>`:''}<div class="notice neutral mt16">디자인 시연입니다. 실제 승인·알림·권한 변경은 일어나지 않습니다.</div>`,btn('취소','data-action="close-dialog"')+btn(status==='approved'?'승인 시연':'보완 요청 시연',`data-confirm-review="${id}" data-status="${status}"`,'primary'));}
function finishReview(id,status){const r=reviews.find(x=>x.id===id);if(!r)return;r.status=status;members[r.member-1].cells[r.day-1]=status;closeDialog();state.currentReview=null;refresh();toast(status==='approved'?'시안에서 승인 상태로 변경했습니다. 다음 제출물을 확인하세요.':'시안에서 보완 요청 상태로 변경했습니다. 실제 알림은 발송하지 않았습니다.');}
function editorDialog(id,type='mission'){const m=missions.find(x=>x.id===id);const title=type==='learning'?'학습 콘텐츠 편집':type==='ongoing'?'상시 챌린지 편집':m?'미션 편집':'미션 등록';showDialog(title,`<label class="field">제목<input id="edit-title" value="${esc(type==='learning'?['Claude란 무엇인가','모델 선택하기','대화 컨텍스트 작동 방식','Context Window 이해하기','주요 활용 사례 탐색'][(id||1)-1]||'':type==='ongoing'?id===1?'오늘의 마케팅 실행':'AI 업무 개선 기록':m?.title||'')}" placeholder="미션의 결과가 드러나는 제목"></label><div class="field-row"><label class="field">주차<select>${[1,2,3,4,5,6].map(w=>`<option ${w===(m?.week||state.missionWeek)?'selected':''}>${w}주차</option>`).join('')}</select></label><label class="field">공개 상태<select><option>공개</option><option ${m&&!m.published?'selected':''}>비공개</option><option>예약 공개</option></select></label></div><label class="field">학습·실습 안내<textarea rows="4">실제 사용하는 브랜드를 기준으로 작업 환경을 설정하고 결과를 기록해 주세요.</textarea></label><div class="field">제출 항목<div class="row wrap"><label><input type="checkbox" checked> 텍스트 답변</label><label><input type="checkbox" checked> 파일</label><label><input type="checkbox"> URL</label></div></div><div class="field-row"><label class="field">확인 퀴즈<select><option>2문항</option><option selected>3문항</option><option>없음</option></select></label><label class="field">완료 조건<select><option>관리자 승인</option><option>제출 즉시 완료</option></select></label></div><details class="guide"><summary>확인 퀴즈 문항 예시</summary><p>질문: AI가 만든 초안에서 먼저 검토할 내용은 무엇인가요?</p><p>① 문장 길이 ② 사실과 브랜드 기준의 일치 ③ 작성 속도</p><p>정답: ② · 해설: 사실 여부와 우리 기준에 맞는지를 먼저 확인합니다.</p></details><div class="notice neutral mt16">제출이 있는 미션을 수정하더라도 과거 답변의 기준은 유지합니다. 이 편집기는 입력·검토 UI만 제공합니다.</div>`,btn('취소','data-action="close-dialog"')+btn('변경 내용 확인','data-action="editor-save"','primary'));}
function nextReview(){let rs=filteredReviews(),i=rs.findIndex(x=>x.id===state.currentReview);if(i<rs.length-1){state.currentReview=rs[i+1].id;refresh();}else toast('현재 목록의 마지막 제출물입니다.');}
const actions={
 'menu':()=>{const side=$('#sidebar'),open=side.classList.toggle('open');const trigger=$('.topbar [data-action="menu"]');trigger?.setAttribute('aria-expanded',String(open));trigger?.setAttribute('aria-controls','sidebar');if(open)side.querySelector('.sidebar-close')?.focus();else trigger?.focus();},
 'close-dialog':closeDialog,
 'cohort':()=>showDialog('기수 선택',`<div class="notice neutral">이번 개편안은 첨부 자료의 1기 회원 13명을 기준으로 구성했습니다.</div><div class="setting-line"><b>AI 온보딩 챌린지 · 1기</b>${badge('현재 선택','green')}</div><p class="meta mt16">다른 기수의 실데이터는 연결하지 않았습니다.</p>`,btn('확인','data-action="close-dialog"','primary')),
 'inactive':()=>{state.memberTab='inactive';go('members')},
 'visitors':()=>{state.memberTab='today';go('members')},
 'criteria':()=>{state.settingsTab='criteria';go('settings')},
 'clear-selection':()=>{state.selected.clear();refresh()},
 'bulk-message':()=>messageDialog([...state.selected]),
 'preview-message':()=>{let text=$('#message-body').value.trim();if(!text){toast('안내 내용을 작성해 주세요.');return;}showDialog('발송 전 미리보기',`<div class="answer-copy">${esc(text)}</div><p class="meta mt16">수신 대상과 내용을 확인하는 단계입니다. 이 HTML에는 실제 발송 기능이 없습니다.</p>`,btn('시연 확인','data-action="close-dialog"','primary'))},
 'review-guide':()=>showDialog('검토 원칙',`<h3>1. 답변과 증빙을 먼저 확인</h3><p class="mt8">미션 원문은 필요할 때 펼쳐 비교합니다.</p><h3 class="mt24">2. 보완 요청에는 이유를 함께</h3><p class="mt8">회원이 무엇을 수정해야 하는지 구체적으로 남깁니다.</p><h3 class="mt24">3. 승인 수와 제출 수를 분리</h3><p class="mt8">제출했다는 사실만으로 완료로 표시하지 않습니다.</p>`,btn('확인','data-action="close-dialog"','primary')),
 'feedback-template':()=>{let r=activeReview();r.feedback='실행 과정을 잘 정리해 주셨습니다. 결과 화면에서 브랜드 기준이 어떻게 반영되었는지 한 가지를 더 설명해 주세요.';$('#review-feedback').value=r.feedback;toast('예시 피드백을 불러왔습니다. 회원의 답변에 맞춰 수정해 주세요.')},
 'save-feedback':()=>{activeReview().feedback=$('#review-feedback').value;toast('피드백을 이 시안 안에만 반영했습니다. 검토 상태는 유지됩니다.')},
 'approve-review':()=>updateReview('approved'),
 'return-review':()=>updateReview('returned'),
 'next-review':nextReview,
 'file-preview':()=>showDialog('첨부 확인',`<div class="file-item"><span class="file-icon">PNG</span><b>프로젝트_설정_화면.png</b></div><div class="notice neutral mt16">실제 회원 첨부 파일이 없어 미리보기 화면은 연결하지 않았습니다. 운영 시 원본 보기·확대·다운로드를 이 영역에서 제공합니다.</div>`,btn('닫기','data-action="close-dialog"','primary')),
 'editor-save':()=>{if(!$('#edit-title').value.trim()){toast('제목을 입력해 주세요.');return;}showDialog('변경 내용 확인',`<h3>${esc($('#edit-title').value)}</h3><p class="mt16">입력과 저장 확인 단계를 보여주는 시안입니다. 실제 콘텐츠·공개 일정·퀴즈에는 반영하지 않았습니다.</p>`,btn('확인','data-action="close-dialog"','primary'))},
 'analytics-date':()=>{let a=$('#analytics-from').value,b=$('#analytics-to').value;if(!a||!b||a>b){toast('조회 시작일과 종료일을 확인해 주세요.');return;}toast('기간 선택 UI입니다. 이 HTML의 숫자는 고정 예시이며 실제 재조회하지 않습니다.')},
 'save-note':()=>toast('버전 변경 메모 저장 UI입니다. 실제 버전 기록에는 반영하지 않았습니다.'),
 'pixel-save':()=>{let id=$('#pixel-id').value.trim(),url=$('#kakao-url').value.trim();if(!/^\d+$/.test(id)||!/^https:\/\//.test(url)){toast('숫자 형식의 픽셀 ID와 https 오픈채팅 URL을 입력해 주세요.');return;}showDialog('설정 변경 확인',`<p>입력값 형식을 확인했습니다. 실제 픽셀 설치·이벤트 수집·발행은 수행하지 않습니다.</p><div class="notice warning mt16">실제 연결 시 픽셀 소유 권한, URL 목적지, 추적·동의 정책을 별도 확인해야 합니다.</div>`,btn('확인','data-action="close-dialog"','primary'))},
 'test-mode':()=>showDialog('테스트 모드 표시 예시',`<div style="background:#ba302a;color:white;text-align:center;padding:14px">이 기기는 테스트 모드입니다 · 이벤트 수집 제외</div><p class="mt16" style="font-size:var(--type-small)">운영자 테스트 기기에만 표시합니다. 이 시안에서는 쿠키를 생성하거나 픽셀을 실행하지 않습니다.</p>`,btn('확인','data-action="close-dialog"','primary')),
 'approval-rule':()=>showDialog('승인 규칙 변경 영향',`<p>선택한 설정: <b>${esc($('#auto-approval').value)}</b></p><div class="divider"></div><label class="checkline"><input type="radio" name="apply-rule" checked>이후 새로 제출하는 미션부터 적용</label><label class="checkline"><input type="radio" name="apply-rule">기존 검토 대기에도 적용 · 대상 확인 필요</label><div class="notice warning mt16">승인 상태나 다음 주차 접근 권한이 실제로 변경되지 않는 디자인 시안입니다.</div>`,btn('취소','data-action="close-dialog"')+btn('확인','data-action="close-dialog"','primary'))
};
document.addEventListener('click',e=>{
 const b=e.target.closest('button,a');if(!b)return;
 if(b.dataset.demo){toast(b.dataset.demo);return;}
 if(b.dataset.go){go(b.dataset.go);return;}
 if(b.dataset.member){memberDialog(+b.dataset.member);return;}
 if(b.dataset.cellMember){cellDialog(+b.dataset.cellMember,+b.dataset.day);return;}
 if(b.dataset.messageMember){messageDialog([+b.dataset.messageMember]);return;}
 if(b.dataset.saveMemberNote){let m=members[+b.dataset.saveMemberNote-1];m.note=$('#member-note').value;toast('내부 메모를 시안 안에만 반영했습니다.');return;}
 if(b.dataset.tab){state[b.dataset.tab]=b.dataset.value;if(b.dataset.tab==='reviewTab')state.currentReview=null;if(b.dataset.tab==='memberTab')state.selected.clear();refresh();return;}
 if(b.dataset.memberTab){state.memberTab=b.dataset.memberTab;state.selected.clear();refresh();return;}
 if(b.dataset.review){state.currentReview=+b.dataset.review;$('#review-content').innerHTML=reviewContent();return;}
 if(b.dataset.confirmReview){finishReview(+b.dataset.confirmReview,b.dataset.status);return;}
 if(b.dataset.missionWeek){state.missionWeek=+b.dataset.missionWeek;refresh();return;}
 if(b.dataset.editMission){editorDialog(b.dataset.editMission==='new'?0:+b.dataset.editMission);return;}
 if(b.dataset.editLearning){editorDialog(b.dataset.editLearning==='new'?0:+b.dataset.editLearning,'learning');return;}
 if(b.dataset.editOngoing){editorDialog(+b.dataset.editOngoing+1,'ongoing');return;}
 if(b.dataset.ongoing!==undefined){showDialog('상시 챌린지 제출 답변',`<p class="meta">정규 미션 승인과 별도로 집계하는 반복 실행 기록입니다.</p>${members.slice(0,5).map((m,i)=>`<div class="setting-line"><button class="btn ghost" data-member="${m.id}">${m.name}</button><span>${i<3?'완료 1회':'답변 1건'} ${badge(i<3?'확인 완료':'미확인',i<3?'green':'amber')}</span></div>`).join('')}<details class="guide mt16"><summary>대표 답변 보기</summary><p>오늘은 브랜드의 반복 업무 중 게시물 초안 작성 단계를 정리했습니다. 내일은 검토 체크리스트를 적용해 보겠습니다.</p></details>`,btn('닫기','data-action="close-dialog"','primary'));return;}
 if(b.dataset.move){let i=missions.findIndex(m=>m.id===+b.dataset.move),j=i+Number(b.dataset.direction);if(missions[j]&&missions[j].week===missions[i].week){[missions[i],missions[j]]=[missions[j],missions[i]];refresh();toast('목록 순서를 시안에서 이동했습니다. 실제 저장은 하지 않습니다.');}return;}
 if(b.dataset.question){let q=questions.find(x=>x.id===+b.dataset.question);showDialog('질문 답변',`<div class="question-meta">${badge('Day '+q.day,'blue')}<b>${members[q.member-1].name}</b></div><h3 class="mt16">${q.title}</h3><p class="mt8" style="font-size:var(--type-small)">${q.body}</p><label class="field mt24">회원에게 보일 답변<textarea id="question-reply" rows="5" placeholder="실행할 수 있는 순서로 답변해 주세요.">${esc(q.reply||'')}</textarea></label><p class="meta">AI 자동 게시 없이 관리자가 내용을 확인하는 단계입니다.</p>`,btn('취소','data-action="close-dialog"')+btn('답변 게시 시연',`data-answer-question="${q.id}"`,'primary'));return;}
 if(b.dataset.answerQuestion){let text=$('#question-reply').value.trim();if(!text){toast('답변 내용을 작성해 주세요.');return;}let q=questions.find(x=>x.id===+b.dataset.answerQuestion);q.reply=text;q.answered=true;closeDialog();refresh();toast('시안에서 답변 완료로 표시했습니다. 실제 알림은 발송하지 않았습니다.');return;}
 if(b.dataset.action&&actions[b.dataset.action])actions[b.dataset.action]();
});
document.addEventListener('input',e=>{let t=e.target;if(t.id==='member-search'){state.memberSearch=t.value;state.selected.clear();$('#bulk-area').innerHTML='';$('#member-table').innerHTML=memberRows();}if(t.id==='review-search'){state.reviewSearch=t.value;state.currentReview=null;$('#review-content').innerHTML=reviewContent();}if(t.id==='review-feedback')activeReview().feedback=t.value;if(t.id==='ad-search'){state.adSearch=t.value;$('#ads-table').innerHTML=adsTable();}if(t.id==='question-search'){state.qSearch=t.value;refresh('question-search');}});
document.addEventListener('change',e=>{let t=e.target;if(t.id==='member-week'){state.week=+t.value;$('#member-table').innerHTML=memberRows();}if(t.dataset.memberSelect){let id=+t.dataset.memberSelect;t.checked?state.selected.add(id):state.selected.delete(id);$('#bulk-area').innerHTML=bulkBar();$('#member-table').innerHTML=memberRows();}if(t.dataset.action==='select-all'){$$('[data-member-select]').forEach(c=>{let id=+c.dataset.memberSelect;t.checked?state.selected.add(id):state.selected.delete(id)});$('#bulk-area').innerHTML=bulkBar();$('#member-table').innerHTML=memberRows();}if(t.dataset.reviewCheck!==undefined)activeReview().checked[+t.dataset.reviewCheck]=t.checked;if(t.id==='review-sort'){state.reviewSort=t.value;state.currentReview=null;$('#review-content').innerHTML=reviewContent();}if(t.id==='campaign'){state.campaign=t.value;state.adSet='all';state.adSearch='';refresh();}if(t.id==='ad-set'){state.adSet=t.value;refresh();}if(t.id==='layout-version'){state.version=t.value;refresh();}});
document.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='manual-form'){const f=new FormData(e.target);const a=f.get('impressions'),b=f.get('clicks');if(a!==''&&b!==''&&+b>+a){toast('링크 클릭이 노출보다 많습니다. 입력값을 다시 확인해 주세요.');return;}showDialog('실측 입력 확인',`<div class="setting-line"><span>기준 날짜 · KST</span><b>${esc(f.get('date'))}</b></div><div class="setting-line"><span>카톡 누적 입장</span><b>${esc(f.get('joins'))}명</b></div><div class="setting-line"><span>라이브 최대 동시시청</span><b>${f.get('live')===''?'미집계':esc(f.get('live'))+'명'}</b></div><div class="setting-line"><span>당일 결제 건수</span><b>${f.get('payments')===''?'미집계':esc(f.get('payments'))+'건'}</b></div><div class="notice neutral mt16">입력 확인용 시안입니다. 기록 내역·퍼널 수치는 갱신하지 않습니다.</div>`,btn('닫기','data-action="close-dialog"','primary'));}if(e.target.id==='criteria-form'){toast('기준 설정 확인 시안입니다. 실제 데이터 재집계나 경고 판정은 실행하지 않습니다.');}});
document.addEventListener('keydown',e=>{const side=$('#sidebar');if(!side?.classList.contains('open'))return;const trigger=$('.topbar [data-action="menu"]');if(e.key==='Escape'){side.classList.remove('open');trigger?.setAttribute('aria-expanded','false');trigger?.focus();}if(e.key==='Tab'){const targets=[...side.querySelectorAll('a,button,summary,input,select')].filter(el=>el.offsetParent!==null);const first=targets[0],last=targets[targets.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog'))closeDialog();});
window.addEventListener('hashchange',()=>{const route=location.hash.slice(1);if(routes[route]){state.route=route;refresh();window.scrollTo(0,0);$('h1')?.focus({preventScroll:true});}});
state.route=routes[location.hash.slice(1)]?location.hash.slice(1):window.INITIAL_ROUTE||'members';
refresh();
